page_paths=[]
def shell(path,title,description,body,active='',tool=False,endcta=True):
 h=head;h=re.sub(r'<title>.*?</title>',f'<title>{e(title)} — Vista Digital</title>',h);h=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{e(description,quote=True)}">',h)
 hh=header
 if active:hh=hh.replace(f'href="/{active}/"',f'href="/{active}/" aria-current="page"',1)
 text=h+'<body><a class="skip" href="#main">Skip to content</a>'+hh+'<main id="main">'+body+(closing if endcta else '')+'</main>'+foot+(dialog if tool else '')+f'<script src="/{"script.js" if tool else "pages.js"}" defer></script></body></html>'
 text=text.replace('src="assets/','src="/assets/')
 out=D/path.strip('/')/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(text);page_paths.append('/'+path.strip('/')+'/')
def hero_page(eyebrow,title,body,active='',image='',caption=''):
 visual=f'<figure class="page-visual"><img src="/assets/existing/{image}" alt="{e(caption)}"><figcaption>{caption}</figcaption></figure>' if image else '<div class="page-route-signal" aria-hidden="true"><span>Visibility</span><i></i><span>Conversion</span><i></i><span>Opportunity</span></div>'
 return f'<section class="wrap page-hero"><p class="breadcrumbs"><a href="/">Vista Digital</a>{chev}<span>{eyebrow}</span></p><div class="page-hero-grid"><div><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="page-lede">{body}</p><div class="page-hero-actions">{link("/assessment/","Get Your Growth Assessment","button orange")}{link("/contact/","Talk to Vista")}</div></div>{visual}</div></section>'
def rows(eyebrow,title,entries):
 return '<section class="wrap section-pad page-section"><div class="section-heading"><div><p class="eyebrow">'+eyebrow+'</p><h2>'+title+'</h2></div><div class="editorial-rows">'+''.join(f'<article><span class="row-number">{i:02}</span><div><h3>{t}</h3><p>{b}</p>{link(u,"Explore "+t) if u else ""}</div></article>' for i,(t,b,u) in enumerate(entries,1))+'</div></div></section>'
def band(label,title,text):return f'<section class="paper section-pad"><div class="wrap two-column"><div><p class="eyebrow">{label}</p><h2>{title}</h2></div><p class="page-band-copy">{text}</p></div></section>'
